// associated node without holding the execution lock. It is called on standby clusters when a
// side-effect task has been pending past the configured discard delay.
//
// When the task validator returns (false, nil), a *serviceerror.NotFound error is returned.
// When the validator returns an error, that error is returned. When the discard handler returns
// an error, that error is returned.
//
// This method panics if called on a task whose executor does not implement SideEffectTaskDiscarder.
//
// ctx should have a CHASM engine already set.
func (n *Node) ExecuteSideEffectDiscardTask(
	ctx context.Context,
	executionKey ExecutionKey,
	chasmTask *tasks.ChasmTask,
	validate func(NodeBackend, Context, Component) error,
) (retErr error) {
	return n.executeSideEffectTask(ctx, executionKey, chasmTask, validate, true)
