	registry *chasm.Registry,
	tree historyi.ChasmTree,
	task *tasks.ChasmTask,
	logger log.Logger,
	clusterName string,
	clientBean client.Bean,
	namespaceRegistry namespace.Registry,
) error {
	// If the execution no longer exists on the source (active) cluster, there is nothing to
	// discard; the task was already handled (or the execution was deleted) on the active side.
	if !executionExistsOnSource(
		ctx,
		taskWorkflowKey(task),
		getTaskArchetypeID(task),
		logger,
		clusterName,
		clientBean,
		namespaceRegistry,
		registry,
